#include <bits/stdc++.h>
using namespace std;
int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);
    vector<pair<int,int>> ops;
    auto apply=[&](int x,int y){
        assert(x>0&&y>0&&x+y<n);
        vector<int> np;
        for(int i=n-y;i<n;i++) np.push_back(p[i]);
        for(int i=x;i<n-y;i++) np.push_back(p[i]);
        for(int i=0;i<x;i++) np.push_back(p[i]);
        p=np;
        ops.push_back({x,y});
    };
    for(int i=0;i<n-1;i++){
        int pos=-1;
        for(int j=i;j<n;j++) if(p[j]==i+1){pos=j;break;}
        if(pos==i) continue;
        int cur=n-(int)ops.size()*0; // remaining size is always n
        // Move element from pos to i
        if(i==0){
            // Just need element at pos to go to 0
            // op(1, n-pos): element at pos, x=1,y=n-pos, x+y=n-pos+1. Need <n => pos>1
            if(pos>1){apply(1,n-pos);} // elem at pos: pos>=x=1, pos<n-y=pos => false. pos==n-y=pos? It's in suffix. new pos=pos-(n-(n-pos))=pos-pos=0. 
            else{/* pos==1 */ apply(1,n-2); for(int j=0;j<n;j++) if(p[j]==i+1){pos=j;break;} if(pos!=0&&pos>1) apply(1,n-pos); else if(pos==1&&n>3) apply(2,n-3),apply(1,n-1>1?n-2:1);}
        } else {
            if(pos<n-1){apply(i,n-pos-1);} // elem goes to n-1-i
            else {apply(i,1);} // pos==n-1, elem in suffix, new pos=n-1-(n-1)=0... then need 0->i
            for(int j=i;j<n;j++) if(p[j]==i+1){pos=j;break;}
            if(pos==i) continue;
            if(pos>0&&pos<n-1&&n-pos-1>0&&pos+n-pos-1<n) apply(pos,n-pos-1); // to pos 0... no
            // try: x=n-i, y=1 if element at n-1-i
            if(pos==n-1-i&&i>0&&n-i+1<n) {apply(n-1-i,1);continue;}
            for(int j=i;j<n;j++) if(p[j]==i+1){pos=j;break;}
            if(pos!=i&&pos>1) apply(1,n-pos);
            for(int j=i;j<n;j++) if(p[j]==i+1){pos=j;break;}
            if(pos==0&&i>0) apply(n-i,1);
        }
    }
    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
